#!/bin/bash
# SPDX-License-Identifier: AGPL-3.0-or-later
# End-to-end tests: real campaigns on small puzzles with keys generated by the independent Python reference.
# Usage: tests/e2e.sh [path/to/pzsolve]   (set E2E_QUICK=1 for a shorter run)
set -u
BIN=${1:-build/pzsolve}
DIR=$(mktemp -d /tmp/pze2e.XXXXXX)
trap 'rm -rf "$DIR"' EXIT
fail=0
ok()   { echo "  OK   $*"; }
bad()  { echo "  FAIL $*"; fail=$((fail+1)); }
vec()  { python3 tools/ref.py "$1"; }   # prints key/pub/h160/addr/wif/x/y lines
field(){ vec "$1" | awk -v k="$2" '$1==k{print $2}'; }
dbfield() { awk -F, -v n="$1" -v c="$2" 'NR>1 && $1==n{print $c}' data/puzzles.csv; }
rndkey() { python3 -c "import random,sys; random.seed($2); n=$1; print(hex(random.randrange(2**(n-1), 2**n)))"; }

echo "== linear search, puzzles 1..24 (random keys)"
MAXN=24; [ "${E2E_QUICK:-0}" = 1 ] && MAXN=18
for n in $(seq 1 $MAXN); do
  K=$(rndkey $n $((n*7+1)))
  A=$(field $K addr)
  $BIN hunt -p $n -a "$A" -c lin$n -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/lin$n/FOUND.txt" 2>/dev/null)
  WANT=${K#0x}
  [ "$GOT" = "$WANT" ] && ok "puzzle $n key $K" || bad "puzzle $n: expected $WANT found '$GOT'"
done

echo "== keys at the ends of the interval (puzzle 20)"
for K in 0x80000 0xfffff; do
  A=$(field $K addr)
  rm -rf "$DIR/edge"
  $BIN hunt -p 20 -a "$A" -c edge -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/edge/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "${K#0x}" ] && ok "end $K" || bad "end $K (found '$GOT')"
done

echo "== reproducible seed: same seed => same order, different seeds => different orders"
A=$(field 0xb3c51 addr)
$BIN hunt -p 20 -a "$A" -c s1 -d "$DIR" -s abc --ui log -q --no-gpu >/dev/null 2>&1
$BIN hunt -p 20 -a "$A" -c s2 -d "$DIR" -s abc --ui log -q --no-gpu >/dev/null 2>&1
$BIN hunt -p 20 -a "$A" -c s3 -d "$DIR" -s xyz --ui log -q --no-gpu >/dev/null 2>&1
W1=$($BIN where -c s1 -d "$DIR" --key b3c51); W2=$($BIN where -c s2 -d "$DIR" --key b3c51); W3=$($BIN where -c s3 -d "$DIR" --key b3c51)
[ "$W1" = "$W2" ] && ok "same seed, same position" || bad "same seed but different positions"
[ "$W1" != "$W3" ] && ok "different seed, different position" || bad "different seed but same position"

echo "== interrupt and resume (linear, puzzle 31)"
K=$(rndkey 31 99); A=$(field $K addr)
timeout -s INT 3 $BIN hunt -p 31 -a "$A" -c res -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
[ -f "$DIR/res/state.dat" ] && ok "checkpoint written" || bad "checkpoint missing"
K1=$(grep -c "^iv" "$DIR/res/state.dat")
$BIN hunt -c res -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
GOT=$(awk '/private key hex/{print $4}' "$DIR/res/FOUND.txt" 2>/dev/null)
[ "$GOT" = "${K#0x}" ] && ok "key found after resuming" || bad "after resuming: expected ${K#0x} found '$GOT'"
OUT=$($BIN hunt -c res -d "$DIR" --ui log -q --no-gpu 2>&1)
echo "$OUT" | grep -q "already found" && ok "a finished campaign is not run again" || bad "finished campaign run again"

echo "== stop with repeated signals in quick succession (timeout sends the signal to the process and to its group)"
A31=$(field 0x5e36d2eb addr)
for i in 1 2 3 4 5; do
  rm -rf "$DIR/sig"
  timeout -s INT 2.5 $BIN hunt -p 31 -a "$A31" -c sig -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  [ -s "$DIR/sig/state.dat" ] || { bad "attempt $i: no checkpoint after the stop"; break; }
  [ $i -eq 5 ] && ok "checkpoint always written on stop (5 attempts)"
done

echo "== kangaroo (public key known)"
for n in 32 38 44 50; do
  K=$(rndkey $n $((n*13+5))); PUB=$(field $K pub); A=$(field $K addr)
  $BIN hunt -p $n -a "$A" -k "$PUB" -m kangaroo -c kang$n -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/kang$n/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "${K#0x}" ] && ok "kangaroo puzzle $n key $K" || bad "kangaroo puzzle $n: expected ${K#0x} found '$GOT'"
done

echo "== kangaroo: resume from the distinguished-point log"
K=$(rndkey 56 4242); PUB=$(field $K pub); A=$(field $K addr)
timeout -s INT 4 $BIN hunt -p 56 -a "$A" -k "$PUB" -m kangaroo -c kres -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
SZ=$(stat -c %s "$DIR/kres/dp.bin" 2>/dev/null || echo 0)
[ "$SZ" -gt 38 ] && ok "distinguished-point log written ($SZ bytes)" || bad "dp.bin empty"
$BIN hunt -c kres -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
GOT=$(awk '/private key hex/{print $4}' "$DIR/kres/FOUND.txt" 2>/dev/null)
[ "$GOT" = "${K#0x}" ] && ok "kangaroo: key found after resuming" || bad "kangaroo resume: expected ${K#0x} found '$GOT'"

echo "== custom intervals (size not a power of two)"
LO=$((0x1000000+5)); HI=$((LO+99999))
for K in $LO $HI $((LO+54321)); do
  KH=$(printf '0x%x' $K); A=$(field $KH addr); rm -rf "$DIR/cus"
  $BIN hunt -r $(printf '%x:%x' $LO $HI) -a "$A" -c cus -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/cus/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "${KH#0x}" ] && ok "linear on an interval of 100000 keys: $KH" || bad "custom interval $KH (found '$GOT')"
done
LO=$((0x7000000000+12345)); W=1000003; HI=$((LO+W-1))
for K in $LO $HI $((LO+W/2)) $((LO+777777)); do
  KH=$(printf '0x%x' $K); P=$(field $KH pub); A=$(field $KH addr); rm -rf "$DIR/cusk"
  $BIN hunt -r $(printf '%x:%x' $LO $HI) -a "$A" -k "$P" -m kangaroo -c cusk -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/cusk/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "${KH#0x}" ] && ok "kangaroo on an interval of $W keys: $KH" || bad "kangaroo custom interval $KH (found '$GOT')"
done

echo "== BSGS in RAM (public key known)"
for n in 30 44 52; do
  rm -rf "$DIR/bs$n"
  $BIN hunt -p $n --mode bsgs -c bs$n -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/bs$n/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "$(dbfield $n 4)" ] && ok "bsgs puzzle $n" || bad "bsgs puzzle $n: expected $(dbfield $n 4) found '$GOT'"
done
LO=$((0x123456789a)); W=3000017
for K in $LO $((LO+W-1)) $((LO+(W-1)/2)) $((LO+1234567)); do
  KH=$(printf '0x%x' $K); P=$(field $KH pub); A=$(field $KH addr); rm -rf "$DIR/bsc"
  $BIN hunt -r $(printf '%x:%x' $LO $((LO+W-1))) -a "$A" -k "$P" -m bsgs -c bsc -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/bsc/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "${KH#0x}" ] && ok "bsgs on an interval of $W keys: $KH" || bad "bsgs custom interval $KH (found '$GOT')"
done
rm -rf "$DIR/bst"
$BIN hunt -p 46 -m bsgs --table "$DIR/t.tbl" -c bst1 -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
[ -s "$DIR/t.tbl" ] && ok "baby-step table saved to file" || bad "table not saved"
OUT=$($BIN hunt -p 47 -m bsgs --table "$DIR/t.tbl" -c bst2 -d "$DIR" --ui log --no-gpu 2>&1)
echo "$OUT" | grep -q "reading the table" && ok "table read back from file for another puzzle" || bad "table not read back"
GOT=$(awk '/private key hex/{print $4}' "$DIR/bst2/FOUND.txt" 2>/dev/null)
[ "$GOT" = "$(dbfield 47 4)" ] && ok "bsgs with table from file: key found" || bad "bsgs with table from file: '$GOT'"
head -c 100000 "$DIR/t.tbl" > "$DIR/trunc.tbl"
$BIN hunt -p 48 -m bsgs --table "$DIR/trunc.tbl" -c bst3 -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1 && bad "truncated table accepted" || ok "truncated table rejected"
rm -rf "$DIR/bsr"
timeout -s INT 3 $BIN hunt -p 60 -m bsgs --bsgs-entries 3000000 -c bsr -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
[ -s "$DIR/bsr/state.dat" ] && ok "BSGS checkpoint written" || bad "BSGS checkpoint missing"
timeout -s INT 3 $BIN hunt -c bsr -d "$DIR" --ui log --no-gpu >"$DIR/bsr.out" 2>&1
SES=$(awk -F= '$1=="sessions"{print $2}' "$DIR/bsr/session.txt")
grep -q "campaign resumed" "$DIR/bsr.out" && [ "$SES" = 2 ] && ok "BSGS resumed from the checkpoint (2 sessions)" || bad "BSGS resume: sessions '$SES'"
# a fatal error after the campaign is open is also written to its log (the terminal alone leaves no trace of why a run stopped)
OUT=$($BIN hunt -c bsr -d "$DIR" --no-cpu --ui log 2>&1); RC=$?
[ $RC -eq 2 ] && echo "$OUT" | grep -q "drop --no-cpu" && tail -n 1 "$DIR/bsr/log.txt" | grep -q -E '^[0-9-]+ [0-9:]+ \[ERROR\] bsgs mode uses the CPU and RAM .*drop --no-cpu$' \
  && ok "a refused resume (BSGS with --no-cpu): the error is the last line of log.txt" || bad "fatal error not in log.txt (rc=$RC): $(tail -n 1 "$DIR/bsr/log.txt")"
# 'where' on a BSGS campaign: the step of a key a quarter and three quarters into the range are different, in order, and below the number of steps
bstep() { $BIN where -c bsr -d "$DIR" --key "$1" | sed -n 's/.*the key will be found at step \([0-9,]*\) of \([0-9,]*\).*/\1 \2/p' | tr -d ,; }
read S1 N1 <<< "$(bstep a00000000000000)"; read S2 N2 <<< "$(bstep e00000000000000)"
[ -n "$S1" ] && [ "$N1" = "$N2" ] && [ "$S1" -gt 0 ] && [ "$S1" -lt "$S2" ] && [ "$S2" -lt "$N1" ] && ok "where for a BSGS campaign: step $S1 and $S2 of $N1" || bad "where BSGS: steps '$S1' '$S2' of '$N1' '$N2'"
$BIN where -c bsr -d "$DIR" --key $(dbfield 60 4) | grep -q "giant step" && ok "where for the key of puzzle 60" || bad "where BSGS (puzzle 60 key)"

echo "== built-in database: automatic target with -p N (already solved puzzles)"
for n in 18 23; do
  rm -rf "$DIR/db$n"
  $BIN hunt -p $n --mode linear -c db$n -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/db$n/FOUND.txt" 2>/dev/null)
  [ "$GOT" = "$(dbfield $n 4)" ] && ok "db linear puzzle $n" || bad "db linear puzzle $n: expected $(dbfield $n 4) found '$GOT'"
done
for n in 36 42; do
  rm -rf "$DIR/dbk$n"
  $BIN hunt -p $n -c dbk$n -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1
  GOT=$(awk '/private key hex/{print $4}' "$DIR/dbk$n/FOUND.txt" 2>/dev/null)
  MODE=$(awk -F= '$1=="mode"{print $2}' "$DIR/dbk$n/campaign.conf")
  [ "$GOT" = "$(dbfield $n 4)" ] && { [ "$MODE" = kangaroo ] || [ "$MODE" = bsgs ]; } && ok "db automatic mode ($MODE) puzzle $n" || bad "db puzzle $n: expected $(dbfield $n 4) found '$GOT' mode '$MODE'"
done
rm -rf "$DIR/stab"
timeout -s INT 2 $BIN hunt -p 33 --mode linear -d "$DIR/stab" --ui log -q --no-gpu >/dev/null 2>&1
[ -s "$DIR/stab/p33/state.dat" ] && ok "stable campaign name p33 created without -c" || bad "campaign p33 not created"
SEED1=$(awk -F= '$1=="seed"{print $2}' "$DIR/stab/p33/campaign.conf")
timeout -s INT 2 $BIN hunt -p 33 --mode linear -d "$DIR/stab" --ui log -q --no-gpu >/dev/null 2>&1
SEED2=$(awk -F= '$1=="seed"{print $2}' "$DIR/stab/p33/campaign.conf")
SES=$(awk -F= '$1=="sessions"{print $2}' "$DIR/stab/p33/session.txt")
[ "$SEED1" = "$SEED2" ] && [ "$SES" = 2 ] && ok "running the same command again resumes the campaign (2 sessions, same seed)" || bad "automatic resume: sessions '$SES'"
[ "$($BIN puzzles | grep -cE '^ *[0-9]+ +(solved|OPEN) ')" = 160 ] && ok "list of the 160 puzzles" || bad "puzzle list incomplete"
$BIN puzzles --open | grep -qE '^ *[0-9]+ +solved ' && bad "--open shows solved puzzles" || ok "--open filter"
for old_opt in --aperti --risolti; do
  $BIN puzzles $old_opt >/dev/null 2>&1 && bad "puzzles $old_opt accepted" || ok "puzzles $old_opt (former Italian spelling) rejected"
done

echo "== campaign lock and the list command"
rm -rf "$DIR/lk"
( $BIN hunt -p 71 -d "$DIR/lk" --ui log -q --no-gpu >/dev/null 2>&1 & echo $! > "$DIR/lk.pid" )
sleep 3
OUT=$($BIN hunt -p 71 -d "$DIR/lk" --ui log -q --no-gpu 2>&1); RC=$?
[ $RC -eq 2 ] && echo "$OUT" | grep -q "already running" && ok "second instance on the same campaign rejected (exit status 2)" || bad "double instance not rejected (rc=$RC)"
LST=$($BIN list -d "$DIR/lk"); echo "$LST" | grep -q "RUNNING" && ok "list shows the running campaign" || bad "list does not see the running campaign"
kill -INT $(cat "$DIR/lk.pid") 2>/dev/null; sleep 2
LST=$($BIN list -d "$DIR/lk"); echo "$LST" | grep -q "STOPPED" && ok "list shows the stopped campaign" || bad "list: state after the stop"
$BIN hunt -p 71 -d "$DIR/lk" --ui log -q --no-gpu >/dev/null 2>&1 & sleep 2; kill -INT $! 2>/dev/null; wait 2>/dev/null
SES=$(awk -F= '$1=="sessions"{print $2}' "$DIR/lk/p71/session.txt"); [ "$SES" = 2 ] && ok "after the stop the campaign resumes (2 sessions)" || bad "resume after the lock: sessions '$SES'"

echo "== info: the state comes from the lock, not only from the report (kill -9 leaves RUNNING in the file)"
rm -rf "$DIR/k9"
( $BIN hunt -p 71 -d "$DIR/k9" --ui log -q --no-gpu -t 2 >/dev/null 2>&1 & echo $! > "$DIR/k9.pid" )
for _ in $(seq 1 200); do [ -s "$DIR/k9/p71/report.txt" ] && break; sleep 0.1; done   # the first report comes 2 s after the start
$BIN info -p 71 -d "$DIR/k9" | grep -q '^State: *RUNNING' && ok "info shows RUNNING while the campaign runs" || bad "info of a running campaign"
kill -9 $(cat "$DIR/k9.pid") 2>/dev/null; sleep 0.5
grep -q '^State: *RUNNING' "$DIR/k9/p71/report.txt" && ok "the report file still says RUNNING after kill -9" || bad "report.txt after kill -9: $(grep '^State:' "$DIR/k9/p71/report.txt")"
$BIN info -p 71 -d "$DIR/k9" | grep -q '^State: *STOPPED' && ok "info shows STOPPED, like list" || bad "info after kill -9: $($BIN info -p 71 -d "$DIR/k9" | grep '^State:')"
$BIN list -d "$DIR/k9" | grep -q 'STOPPED' || bad "list after kill -9"

echo "== exit status of hunt: 0 key found, 1 finished without the key, 130 interrupted, 2 error"
K=$(rndkey 18 5); A=$(field $K addr)
$BIN hunt -p 18 -a "$A" -c xf -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1; RC=$?
[ $RC -eq 0 ] && ok "key found: exit status 0" || bad "key found: exit status $RC"
$BIN hunt -c xf -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1; RC=$?
[ $RC -eq 0 ] && ok "campaign that had already found the key: exit status 0" || bad "already found: exit status $RC"
A=$(field 0x20000 addr)   # well above the range 1:ffff (the last block may be scanned a few keys past the end)
$BIN hunt -r 1:ffff -a "$A" -c xn -d "$DIR" --ui log -q --no-gpu >"$DIR/xn.out" 2>&1; RC=$?
[ $RC -eq 1 ] && grep -q "Campaign completed" "$DIR/xn.out" && ok "range covered without the key: exit status 1" || bad "range covered without the key: exit status $RC"
$BIN hunt -c xn -d "$DIR" --ui log -q --no-gpu >/dev/null 2>&1; RC=$?
[ $RC -eq 1 ] && ok "campaign already completed: exit status 1" || bad "already completed: exit status $RC"
A=$(field 0x200000 addr)
$BIN hunt -r 1:fffff -a "$A" --part 0/2 -c xp -d "$DIR" --ui log -q --no-gpu >"$DIR/xp.out" 2>&1; RC=$?
[ $RC -eq 1 ] && grep -q "Part 0/2 was scanned in full" "$DIR/xp.out" && ok "share of a split range covered without the key: exit status 1" || bad "share covered without the key: exit status $RC"
for sig in INT TERM; do
  rm -rf "$DIR/xi"
  $BIN hunt -p 71 -c xi -d "$DIR/xi" --ui log -q --no-gpu >/dev/null 2>&1 & XPID=$!
  for _ in $(seq 1 300); do [ -s "$DIR/xi/xi/report.txt" ] && break; sleep 0.1; done   # running: the first report comes 2 s after the start
  kill -$sig $XPID 2>/dev/null; wait $XPID; RC=$?
  [ $RC -eq 130 ] && [ -s "$DIR/xi/xi/state.dat" ] && ok "SIG$sig: state saved, exit status 130" || bad "SIG$sig: exit status $RC"
done
$BIN hunt -p 40 -t 0 -c xe -d "$DIR" -q >/dev/null 2>&1; RC=$?
[ $RC -eq 2 ] && ok "invalid option: exit status 2" || bad "invalid option: exit status $RC"
$BIN hunt -p 40 --resume -c xe -d "$DIR" -q >/dev/null 2>&1; RC=$?
[ $RC -eq 2 ] && ok "--resume of a campaign that does not exist: exit status 2" || bad "--resume without a campaign: exit status $RC"
$BIN frobnicate >/dev/null 2>&1; RC=$?
[ $RC -eq 2 ] && ok "unknown command: exit status 2" || bad "unknown command: exit status $RC"
# merge: 0 when the files are merged without a collision, 1 when a file cannot be merged, 2 for a campaign that cannot take it
rm -rf "$DIR/xm" "$DIR/xm2"
$BIN hunt -p 120 -c xk -d "$DIR/xm" --ui log -q --no-gpu >/dev/null 2>&1 & XPID=$!
for _ in $(seq 1 300); do [ -s "$DIR/xm/xk/report.txt" ] && break; sleep 0.1; done
kill -INT $XPID 2>/dev/null; wait $XPID
mkdir -p "$DIR/xm2"; cp -r "$DIR/xm/xk" "$DIR/xm2/xk"
OUT=$($BIN merge -c xk -d "$DIR/xm" -f "$DIR/xm2/xk" 2>&1); RC=$?
[ $RC -eq 0 ] && echo "$OUT" | grep -q "No collision" && ok "merge without a collision: exit status 0" || bad "merge without a collision: exit status $RC"
$BIN merge -c xk -d "$DIR/xm" -f "$DIR/xm2/nonexistent.bin" >/dev/null 2>&1; RC=$?
[ $RC -eq 1 ] && ok "merge of a file that cannot be read: exit status 1" || bad "merge of an unreadable file: exit status $RC"
$BIN merge -c xn -d "$DIR" -f "$DIR/xm2/xk" >/dev/null 2>&1; RC=$?
[ $RC -eq 2 ] && ok "merge into a campaign that is not a kangaroo one: exit status 2" || bad "merge into a linear campaign: exit status $RC"

echo "== campaign creation: simultaneous starts, and the seed recorded in the state"
seedid() { python3 -c "import hashlib,sys; print(hashlib.sha256(b'PZID'+bytes.fromhex(sys.argv[1])).hexdigest()[:16])" "$1"; }
for attempt in 1 2; do
  rm -rf "$DIR/race"; pids=""
  for i in 1 2 3 4 5 6 7 8; do
    timeout -s INT 3 $BIN hunt -p 66 -m linear -c rc -d "$DIR/race" --ui log --no-gpu -t 1 >"$DIR/race$i.out" 2>&1 &
    pids="$pids $!"
  done
  wait $pids 2>/dev/null
  CONFSEED=$(awk -F= '$1=="seed"{print $2}' "$DIR/race/rc/campaign.conf")
  REPSEED=$(grep -o 'seed id [0-9a-f]*' "$DIR/race/rc/report.txt" | awk '{print $3}')
  NLOSE=$(grep -l "already running" "$DIR"/race[1-8].out | wc -l)
  [ -n "$CONFSEED" ] && [ "$(seedid "$CONFSEED")" = "$REPSEED" ] && [ "$NLOSE" = 7 ] || break
done
[ -n "$CONFSEED" ] && [ "$(seedid "$CONFSEED")" = "$REPSEED" ] && [ "$NLOSE" = 7 ] && ok "8 simultaneous starts: one campaign, one seed in campaign.conf and in the report (2 attempts)" || bad "simultaneous starts: conf seed id '$(seedid "$CONFSEED")', report '$REPSEED', $NLOSE refused"
rm -rf "$DIR/sd"
for c in sa sb sc; do
  timeout -s INT 2 $BIN hunt -p 40 -m linear -s seed-$c -c $c -d "$DIR/sd" --ui log -q --no-gpu -t 1 >/dev/null 2>&1
done
grep -q '^seed_id=' "$DIR/sd/sa/state.dat" && ok "the state records the seed id" || bad "state.dat without seed_id"
cp "$DIR/sd/sa/state.dat" "$DIR/sd/sb/state.dat"; rm -f "$DIR/sd/sb/state.dat.bak"; cp "$DIR/sd/sb/state.dat" "$DIR/sd/sb.keep"
OUT=$(timeout -s INT 5 $BIN hunt -c sb -d "$DIR/sd" --ui log --no-gpu -t 1 2>&1); RC=$?
[ $RC -ne 0 ] && echo "$OUT" | grep -q "another seed" && cmp -s "$DIR/sd/sb/state.dat" "$DIR/sd/sb.keep" && ok "a state of another seed is refused and left untouched" || bad "state of another seed accepted (rc=$RC)"
grep -q '\[ERROR\].*another seed' "$DIR/sd/sb/log.txt" && ok "the refusal is in the log of the campaign" || bad "the refusal is not in sb/log.txt"
python3 - "$DIR/sd/sa/state.dat" "$DIR/sd/sc/state.dat" <<'PYEOF'
import hashlib, sys
t = open(sys.argv[1]).read()
body = "".join(l + "\n" for l in t[:t.index("crc=")].splitlines() if not l.startswith("seed_id="))
open(sys.argv[2], "w").write(body + "crc=" + hashlib.sha256(body.encode()).hexdigest()[:16] + "\n")
PYEOF
rm -f "$DIR/sd/sc/state.dat.bak"
OUT=$(timeout -s INT 3 $BIN hunt -c sc -d "$DIR/sd" --ui log --no-gpu -t 1 2>&1)
echo "$OUT" | grep -q "campaign resumed" && ok "a state without seed id (earlier versions) is still accepted" || bad "state of an earlier version refused"
grep -q '^seed_id=' "$DIR/sd/sc/state.dat" && ok "the next save records the seed id" || bad "seed_id not recorded after resuming an old state"

echo "== input error checks"
$BIN hunt -p 20 -a 1BgGZ9tcN4rm9KBzDn7KprQz87SZ26SAMX -c bad -d "$DIR" -q >/dev/null 2>&1 && bad "address with a wrong checksum accepted" || ok "address with a wrong checksum rejected"
$BIN hunt -r 1:ffff -c bad2 -d "$DIR" -q >/dev/null 2>&1 && bad "missing target accepted" || ok "missing target rejected"
$BIN hunt -p 257 -c bad4 -d "$DIR" -q >/dev/null 2>&1 && bad "puzzle 257 accepted" || ok "puzzle 257 rejected"
timeout -s INT 2 $BIN hunt -p 161 -c p161 -d "$DIR" --ui log --no-gpu -t 1 >"$DIR/p161.out" 2>&1
grep -q "emptied by the creator" "$DIR/p161.out" && grep -q "^address=1JkqBQcC4tHcb1JfdCH6nrWYwTPGznHANh" "$DIR/p161/campaign.conf" 2>/dev/null \
  && ok "puzzle 161 (emptied): warning and address from the database" || bad "puzzle 161: warning or address missing"
$BIN hunt -p 20 -a 1BgGZ9tcN4rm9KBzDn7KprQz87SZ26SAMH -k 02e0cd1ed3ab4d2d3d6f3c2b1a5c4f3e2d1c0b9a8f7e6d5c4b3a291807f6e5d4c3 -c bad3 -d "$DIR" -q >/dev/null 2>&1 && bad "invalid pubkey accepted" || ok "invalid pubkey rejected"
# the kangaroo takes at most 2^188 keys: one key more (puzzle 190 and above, or a custom interval) is refused with the reason, before a campaign is created
KP=$(field 0x1234567 pub); KA=$(field 0x1234567 addr)
for kopts in "-m kangaroo" "-m auto"; do
  rm -rf "$DIR/wide"
  OUT=$($BIN hunt -r 1:$(printf '1%047d' 1) -a "$KA" -k "$KP" $kopts -c wide -d "$DIR/wide" --ui log -q --no-gpu 2>&1); RC=$?
  [ $RC -ne 0 ] && echo "$OUT" | grep -q "range too large for the kangaroo (maximum 2^188" && { [ ! -e "$DIR/wide" ] || [ -z "$(ls -A "$DIR/wide" 2>/dev/null)" ]; } \
    && ok "interval of 2^188 + 1 keys refused ($kopts), nothing left behind" || bad "interval of 2^188 + 1 keys with $kopts (rc=$RC): $OUT"
done

echo "== invalid options: clear error and no half-created campaign left behind"
for bad_opts in "-t 0" "-t 12abc" "-p 40x" "--mem abc" "--chunk-bits 99" "--dp-bits -1" "--report-interval 0" "--bsgs-entries 0" "--isa foo" "--no-cpu --no-gpu" "-c ../x" "-c .hidden" "-c con" "-c NUL" "-c com1" "-c LPT9.txt" "-c aux.x" "-c trailing." "--ui fancy" "--chunk-bits 10" "--gpu 99" "--gpu 0,," "--gpu ''" "71" "--new --resume" "-m bsgs --no-cpu" "-m bsgs --table /nonexistent_dir/x.tbl" "-m bsgs --mem 0.0001 --bsgs-entries 1000000" "-m bsgs --bsgs-entries 900000000000" "-m linear --node 3" "--retune --limit 50" "--ritara" "--no-taratura" "--sveglio" "--nodo 3" "--parte 0/2" "--limite 50" "--prio-gpu si"; do
  rm -rf "$DIR/opt"
  $BIN hunt -p 40 $bad_opts -d "$DIR/opt" -q >/dev/null 2>&1 && bad "options '$bad_opts' accepted" || { [ ! -e "$DIR/opt" ] || [ -z "$(ls -A "$DIR/opt" 2>/dev/null)" ] && ok "options '$bad_opts' rejected without leaving files" || bad "options '$bad_opts' left a campaign behind"; }
done

# a refusal that needs the whole configuration (the range of puzzle 130 is too large for BSGS) comes before the folder is created too
rm -rf "$DIR/opt"
$BIN hunt -p 130 -m bsgs -d "$DIR/opt" -q >/dev/null 2>&1 && bad "bsgs on puzzle 130 accepted" || { [ -z "$(ls -A "$DIR/opt" 2>/dev/null)" ] && ok "bsgs on puzzle 130 rejected without leaving files" || bad "bsgs on puzzle 130 left a campaign behind"; }

echo "== option values: errors named after the right option, values that do not fit are refused, not cut"
mkdir -p "$DIR/ov"; BINABS=$(readlink -f "$BIN"); LONG=$(python3 -c "print('x'*700)")
chk() {   # chk FRAGMENT COMMAND...: fails with that text, in a folder of its own where nothing may be created
  local frag=$1 out rc label; shift
  label=$(printf '%s ' "$@" | sed -E 's/[^ ]{40,}/<long>/g')
  out=$(cd "$DIR/ov" && timeout 20 "$BINABS" "$@" 2>&1 </dev/null); rc=$?
  [ $rc -ne 0 ] && echo "$out" | grep -q -- "$frag" && [ -z "$(ls -A "$DIR/ov")" ] && ok "$label: '$frag'" || bad "$label: rc=$rc: $(echo "$out" | head -1 | cut -c1-120)"
}
chk "unrecognized option '-x'" hunt -xq
chk "unrecognized option '-x'" hunt -p 20 -qx
chk "unrecognized option '--nonsense'" hunt --nonsense
chk "the option '-p' needs a value" hunt -qp
chk "--dir: invalid value ''" list -d ""
chk "--dir: the value is too long" hunt -p 20 -d "$LONG" -q
chk "--range: the value is too long" hunt -r "$LONG" -a 1BgGZ9tcN4rm9KBzDn7KprQz87SZ26SAMH -q
chk "--table: the value is too long" hunt -p 46 -m bsgs --table "$LONG" -q
chk "--file: the value is too long" merge -c x -f "$LONG"
chk "at most 1000000000" hunt -p 20 --mem 1e12 -q
chk "--mem: invalid value 'inf'" hunt -p 20 --mem inf -q

echo "== range option: the same messages for a new campaign and for a resume"
rm -rf "$DIR/rg"; A1=1BgGZ9tcN4rm9KBzDn7KprQz87SZ26SAMH
$BIN hunt -r 1:ffff -a $A1 -c rg -d "$DIR/rg" --ui log -q --no-gpu >/dev/null 2>&1
for pair in "1000|requires the format START:END" "1:zz|invalid hexadecimal values"; do
  RNG=${pair%%|*}; MSG=${pair#*|}
  OUT1=$($BIN hunt -r "$RNG" -a $A1 -c rgnew -d "$DIR/rg" -q --no-gpu 2>&1); RC1=$?
  OUT2=$($BIN hunt -r "$RNG" -c rg -d "$DIR/rg" -q --no-gpu 2>&1); RC2=$?
  [ $RC1 -ne 0 ] && [ $RC2 -ne 0 ] && echo "$OUT1" | grep -q "$MSG" && echo "$OUT2" | grep -q "$MSG" && ok "-r $RNG: '$MSG' (new campaign and resume)" || bad "-r $RNG: messages '$OUT1' / '$OUT2'"
done
OUT=$($BIN hunt -r 1:fff -c rg -d "$DIR/rg" -q --no-gpu 2>&1); RC=$?
[ $RC -ne 0 ] && echo "$OUT" | grep -q "does not match the range of the existing campaign" && ok "-r with another range than the campaign's rejected" || bad "resume with another range: rc=$RC"
$BIN hunt -r 0001:FFFF -c rg -d "$DIR/rg" -q --no-gpu >/dev/null 2>&1 && ok "-r 0001:FFFF is the range 1:ffff (leading zeros and case do not matter)" || bad "-r 0001:FFFF refused on resume"
[ ! -e "$DIR/rg/rgnew" ] && ok "the refused commands left no folder" || bad "a refused -r left a folder"

echo "== resume: options that conflict with the existing campaign"
rm -rf "$DIR/rc"
timeout -s INT 2 $BIN hunt -p 71 -d "$DIR/rc" --ui log -q --no-gpu >/dev/null 2>&1
for conflict in "-s somethingelse" "--chunk-bits 20" "-m kangaroo" "-m bsgs" "-r 400000000000000000:5fffffffffffffffff" "-a 1BgGZ9tcN4rm9KBzDn7KprQz87SZ26SAMH" "--new"; do
  OUT=$(timeout -s INT 4 $BIN hunt -c p71 -p 71 $conflict -d "$DIR/rc" --ui log --no-gpu 2>&1); RC=$?
  [ $RC -ne 0 ] && echo "$OUT" | grep -q "ERROR" && ok "resume with '$conflict' rejected" || bad "resume with '$conflict' accepted (rc=$RC)"
done
SES=$(awk -F= '$1=="sessions"{print $2}' "$DIR/rc/p71/session.txt"); [ "$SES" = 1 ] && ok "the rejections left the campaign untouched (1 session)" || bad "sessions after the rejections: '$SES'"

echo "== resume with the command that created the campaign, also when an option was cut down"
rm -rf "$DIR/cb"; A1=1BgGZ9tcN4rm9KBzDn7KprQz87SZ26SAMH
# a range of 2^18 keys is smaller than a block of 2^30: the campaign gets blocks of its own size, and the same command must resume it
for i in 1 2; do
  OUT=$($BIN hunt -r 100000000000:10000003ffff -a $A1 --chunk-bits 30 -c cb -d "$DIR/cb" --ui log --no-gpu -t 1 2>&1); RC=$?
  [ $RC -eq 1 ] && ok "--chunk-bits 30 on a range of 2^18 keys: run $i (exit status 1: covered without the key)" || bad "--chunk-bits 30 on a small range, run $i: rc=$RC $(echo "$OUT" | grep ERROR)"
done
grep -q '^chunk_bits=18$' "$DIR/cb/cb/campaign.conf" && ok "the campaign has blocks of 2^18 keys" || bad "chunk_bits: $(grep chunk_bits "$DIR/cb/cb/campaign.conf")"
# a table file that exists decides the size of the table, whatever --bsgs-entries says: the same command resumes the campaign
for i in 1 2; do
  OUT=$($BIN hunt -p 47 -m bsgs --table "$DIR/t.tbl" --bsgs-entries 777 -c bst4 -d "$DIR" --ui log --no-gpu 2>&1); RC=$?
  [ $RC -eq 0 ] && ok "--table and --bsgs-entries together: run $i" || bad "--table with --bsgs-entries, run $i: rc=$RC $(echo "$OUT" | grep ERROR)"
done
OUT=$($BIN hunt -c bst4 -d "$DIR" --bsgs-entries 777 --ui log --no-gpu 2>&1); RC=$?
[ $RC -ne 0 ] && echo "$OUT" | grep -q "bsgs-entries cannot be changed" && ok "--bsgs-entries alone cannot change the table of the campaign" || bad "--bsgs-entries 777 without the table on resume: rc=$RC"

echo "== sub-interval of a puzzle: same command = same campaign"
rm -rf "$DIR/sub"
for i in 1 2; do timeout -s INT 2 $BIN hunt -p 71 -r 0x400000000000000000:0x4fffffffffffffffff -d "$DIR/sub" --ui log -q --no-gpu >/dev/null 2>&1; done
NC=$(ls -d "$DIR"/sub/p71-* 2>/dev/null | wc -l); SES=$(awk -F= '$1=="sessions"{print $2}' "$DIR"/sub/p71-*/session.txt 2>/dev/null)
[ "$NC" = 1 ] && [ "$SES" = 2 ] && ok "a single campaign with 2 sessions" || bad "sub-interval: $NC campaigns, sessions '$SES'"
$BIN hunt -p 71 -r 0x1:0x3f -d "$DIR/sub" --ui log -q --no-gpu >/dev/null 2>&1 && bad "interval outside the puzzle accepted" || ok "interval that does not intersect the puzzle rejected"

echo "== status.json lists every worker; a campaign.conf with a mode this version does not know is refused"
rm -rf "$DIR/sj"
timeout -s INT 4 $BIN hunt -p 71 -m linear -t 200 -d "$DIR/sj" --ui log -q --no-gpu >/dev/null 2>&1
python3 -c "import json,sys; d=json.load(open(sys.argv[1])); sys.exit(0 if len(d['workers']) == 200 and d['workers'][199]['name'] == 'CPU199' else 1)" "$DIR/sj/p71/status.json" 2>/dev/null \
  && ok "status.json: 200 workers listed, valid JSON" || bad "status.json with 200 workers"
rm -rf "$DIR/um"; mkdir -p "$DIR/um"; cp -r "$DIR/rc/p71" "$DIR/um/p71"; sed -i 's/^mode=.*/mode=quantum/' "$DIR/um/p71/campaign.conf"
OUT=$($BIN list -d "$DIR/um" 2>&1); echo "$OUT" | grep -q "unknown mode 'quantum'" && ok "list: unknown mode reported" || bad "list with an unknown mode: $OUT"
OUT=$(timeout 10 $BIN hunt -c p71 -d "$DIR/um" --ui log -q --no-gpu 2>&1); RC=$?
[ $RC -ne 0 ] && echo "$OUT" | grep -q "unknown mode 'quantum'" && ok "hunt: a campaign of an unknown mode is not run as a linear one" || bad "hunt with an unknown mode: rc=$RC"

echo "== terminal closed (SIGHUP): orderly stop with save"
# Under nohup SIGHUP arrives already ignored, the shell cannot restore it and the program rightly keeps ignoring it
if [ $(( 0x$(awk '/^SigIgn:/{print $2}' /proc/$$/status 2>/dev/null || echo 0) & 1 )) -eq 1 ]; then
  ok "SIGHUP: skipped (ignored by the environment, e.g. nohup: the program deliberately respects that)"
else
rm -rf "$DIR/hup"
( $BIN hunt -p 71 -d "$DIR/hup" --ui log -q --no-gpu >/dev/null 2>&1 & echo $! > "$DIR/hup.pid" )
sleep 3; kill -HUP $(cat "$DIR/hup.pid") 2>/dev/null
# the stop takes ~2 s (the workers finish their current job): wait up to 10 s instead of a fixed 2 s that was right at the edge
for _ in $(seq 1 100); do kill -0 $(cat "$DIR/hup.pid") 2>/dev/null || break; sleep 0.1; done
if kill -0 $(cat "$DIR/hup.pid") 2>/dev/null; then bad "the process did not stop on SIGHUP"; kill -INT $(cat "$DIR/hup.pid"); else
  SES=$(awk -F= '$1=="sessions"{print $2}' "$DIR/hup/p71/session.txt" 2>/dev/null)
  [ -s "$DIR/hup/p71/state.dat" ] && [ "$SES" = 1 ] && ok "SIGHUP: state saved (session recorded)" || bad "SIGHUP: state not saved"
fi
fi

echo "== scratch folders of the self-tests and measurements: an abandoned one is removed, the others are left alone"
mkdir -p "$DIR/tmp"
for n in DEAD01 LIVE01 FRESH1 FOREIGN; do mkdir -p "$DIR/tmp/pzkang$n"; done
for n in DEAD01 LIVE01 FRESH1; do : > "$DIR/tmp/pzkang$n/owner"; done
: > "$DIR/tmp/pzkangDEAD01/dp.bin"
python3 -c "import fcntl,sys,time; f=open(sys.argv[1]); fcntl.flock(f, fcntl.LOCK_EX); print('locked', flush=True); time.sleep(3)" "$DIR/tmp/pzkangLIVE01/owner" >"$DIR/lock.out" &
for _ in $(seq 1 50); do grep -q locked "$DIR/lock.out" && break; sleep 0.1; done
touch -d '10 minutes ago' "$DIR/tmp/pzkangDEAD01" "$DIR/tmp/pzkangLIVE01" "$DIR/tmp/pzkangFOREIGN"   # FRESH1 stays new: it may be being made
TMPDIR="$DIR/tmp" $BIN kstat 16 1 1 >/dev/null 2>&1
[ ! -e "$DIR/tmp/pzkangDEAD01" ] && ok "the folder of a program that is gone (free lock, not new) is removed" || bad "abandoned scratch folder left"
[ -d "$DIR/tmp/pzkangLIVE01" ] && ok "a folder whose lock is held is left alone" || bad "scratch folder in use removed"
[ -d "$DIR/tmp/pzkangFRESH1" ] && [ -d "$DIR/tmp/pzkangFOREIGN" ] && ok "a new folder and one without owner file are left alone" || bad "a scratch folder that is not abandoned was removed"
[ "$(ls "$DIR/tmp" | wc -l)" = 3 ] && ok "the folder of the run itself is removed at its end" || bad "scratch folders left: $(ls "$DIR/tmp" | tr '\n' ' ')"
wait

echo "== doctor counts the suspensions in a big log (read in blocks, a phrase across the end of a block counts once)"
rm -rf "$DIR/dr"; mkdir -p "$DIR/dr"; cp -r "$DIR/rc/p71" "$DIR/dr/p71"
python3 - "$DIR/dr/p71/log.txt" <<'PYEOF'
import sys
line = "2026-01-01 00:00:00 [INFO] filler line of an ordinary message\n"
sus = "2026-01-01 00:00:00 [WARN] system suspension detected (about 1m 0s without computing)\n"
text = line * 1200
text = text[:65536 - 40] + sus + text[65536 - 40:]            # across the end of the first block
text = text + sus + line * 90000 + sus                        # then in the middle and at the end of a log of 5 MB
open(sys.argv[1], "w").write(text)
PYEOF
OUT=$($BIN doctor -d "$DIR/dr" 2>&1)
echo "$OUT" | grep -q "system suspensions detected during the campaign: 3 " && ok "doctor: 3 suspensions in a log of $(stat -c %s "$DIR/dr/p71/log.txt") bytes" || bad "doctor suspensions: $(echo "$OUT" | grep suspensions)"

echo "== line width: nothing printed is longer than 128 columns"
chk_width() {   # chk_width LABEL COMMAND...: the longest line of stdout and stderr
  local label=$1 out w; shift
  out=$(timeout 300 "$@" 2>&1 </dev/null)
  w=$(printf '%s\n' "$out" | tr -d '\r' | python3 -c "import sys; print(max((len(l.rstrip('\n')) for l in sys.stdin), default=0))")
  [ "$w" -le 128 ] && ok "$label (longest line: $w)" || bad "$label: a line of $w columns"
}
chk_width "help" $BIN help
chk_width "hunt --help" $BIN hunt --help
chk_width "puzzles" $BIN puzzles
chk_width "puzzle 71" $BIN puzzle 71
chk_width "puzzle 140" $BIN puzzle 140
chk_width "devices" $BIN devices
chk_width "list" $BIN list -d "$DIR/rc"
chk_width "info" $BIN info -c p71 -d "$DIR/rc"
chk_width "where" $BIN where -c p71 -d "$DIR/rc" --key 400000000000000123
chk_width "split" $BIN split 800M 120M 50M
chk_width "doctor" $BIN doctor -d "$DIR/rc"
chk_width "selftest" $BIN selftest
chk_width "hunt, linear search" timeout -s INT 4 $BIN hunt -p 71 -m linear -d "$DIR/w1" --ui log --no-gpu
chk_width "hunt, kangaroo" timeout -s INT 6 $BIN hunt -p 120 -d "$DIR/w2" --ui log --no-gpu
chk_width "hunt, BSGS to the key" $BIN hunt -p 30 -d "$DIR/w3" --ui log --no-gpu
chk_width "error: unknown option" $BIN hunt -p 71 --nonsense
chk_width "error: conflict with a campaign" $BIN hunt -p 71 -c p71 -d "$DIR/rc" -s somethingelse
chk_width "merge usage" $BIN merge

echo
if [ $fail -eq 0 ]; then echo "E2E PASSED"; else echo "E2E FAILED: $fail errors"; fi
exit $fail
